#[cfg(test)]
mod allocation_probe {
    use super::*;
    use crate::{executor_allocation_meter as meter,resources::Scope,vt::Parser};
    #[derive(Clone,Copy)]struct Sample{step:&'static str,c:meter::Counts,used:usize,peak:usize}
    fn sample(step:&'static str,pool:&Arc<Budget>)->Sample{let c=meter::peek();let b=pool.snapshot();if !(c.live>=0&&c.live as usize==b.used&&c.peak as usize<=b.peak){meter::stop();panic!("unfunded {step}:live={} used={} peak={} budget_peak={}",c.live,b.used,c.peak,b.peak);}Sample{step,c,used:b.used,peak:b.peak}}
    #[test]
    fn measured_pool_growth_prune_url_handoff_and_refusal(){
        let pool=Budget::new(4*1024*1024,0);let other=Budget::new(0,0);let url="https://h/".to_owned()+&"x".repeat(64);let mut links={let _scope=Scope::enter(pool.clone());Links::default()};let _scope=Scope::enter(other.clone());let _=pool.snapshot();let _=other.snapshot();
        let mut growth=[None;9];let mut count=0;let mut capacity=0;meter::start();for line in 0..ENTRY_LIMIT{assert_ne!(links.insert(&url,line as u64),0);if capacity!=links.entries.capacity(){capacity=links.entries.capacity();growth[count]=Some((line+1,capacity,sample("growth",&pool)));count+=1;}}let a=sample("full",&pool);assert_eq!(a.used,links.resource_bytes());let before=meter::peek();for id in 1..=ENTRY_LIMIT as u32{assert_eq!(links.get(id),Some(url.as_str()));links.touch(id,2000);}let after=meter::peek();assert_eq!((before.allocations,before.reallocations),(after.allocations,after.reallocations));let b=sample("lookup",&pool);
        links.prune(3000,1);let c=sample("pruned",&pool);assert_eq!(links.entries.len(),1);let owned=Url::new(links.get(1).unwrap(),&pool).unwrap();let pointer=owned.as_ptr();let request=crate::platform::CopyText::from_url(owned,1);assert_eq!(request.as_ptr(),pointer);let d=sample("copied",&pool);drop(links);let e=sample("source_dropped",&pool);assert_eq!(e.used,url.len());let hold=pool.lease(Kind::Queue,pool.snapshot().limit-pool.snapshot().used).unwrap();let before=meter::peek();let mut denied=Links::default(); // belongs to zero current pool
        assert_eq!(denied.insert(&url,0),0);assert!(Url::new(&url,&pool).is_none());let after=meter::peek();assert_eq!((before.allocations,before.reallocations),(after.allocations,after.reallocations));drop((hold,denied,request));let f=sample("released",&pool);assert_eq!((f.c.live,f.used),(0,0));assert_eq!(other.snapshot().used,0);assert_eq!(meter::stop().live,0);for s in [a,b,c,d,e,f]{eprintln!("LINK_ALLOC step={} live={} peak={} used={} budget_peak={} allocations={} reallocations={}",s.step,s.c.live,s.c.peak,s.used,s.peak,s.c.allocations,s.c.reallocations);}for (entries,capacity,s) in growth.into_iter().flatten(){eprintln!("LINK_GROW entries={entries} capacity={capacity} live={} peak={} used={} budget_peak={}",s.c.live,s.c.peak,s.used,s.peak);}eprintln!("LINK_FINAL denied_new_allocations=0 lookup_new_allocations=0 final=0 entry_size={}",std::mem::size_of::<Entry>());
    }
    #[test]
    fn measured_visible_and_osc_hits_only_allocate_the_paid_final_url(){
        let pool=Budget::new(32*1024*1024,0);let _scope=Scope::enter(pool.clone());let mut term=Terminal::new(120,8);Parser::new().advance(&mut term,"(https://example.com/文e\u{301}). next\r\n\x1b]8;;https://osc.example/a;b\x07label\x1b]8;;\x07\r\nnot-a-url".as_bytes());let _=pool.snapshot();
        meter::start();let before=meter::peek();assert!(at(&term,Point{line:2,col:3}).is_none());let after=meter::peek();assert_eq!((before.allocations,before.reallocations),(after.allocations,after.reallocations));let visible=at(&term,Point{line:0,col:10}).unwrap();let osc=at(&term,Point{line:1,col:1}).unwrap();let live=meter::peek();assert_eq!(live.live as usize,visible.url.len()+osc.url.len());assert_eq!((live.allocations,live.reallocations),(2,0));let paid=pool.snapshot().kinds[Kind::Links as usize];assert!(paid>=live.live as usize);let pointer=visible.url.as_ptr();let request=crate::platform::CopyText::from_url(visible.url,7);assert_eq!(pointer,request.as_ptr());drop((osc,term));assert_eq!(pool.snapshot().used,request.len());drop(request);assert_eq!(pool.snapshot().used,0);assert_eq!(meter::stop().live,0);eprintln!("LINK_HITS allocations=2 reallocations=0 live={} invalid_new_allocations=0 handoff_new_allocations=0 final=0",live.live);
    }
}
